def main():
    target_dir = os.path.join(os.path.dirname(__file__), "data")
    os.makedirs(target_dir, exist_ok=True)
    target_file = os.path.join(target_dir, "municipal_complaints_dev.csv")
    
    with open(target_file, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["id", "title", "description", "category", "urgency_hint"])
        for idx, (title, desc, cat, urg) in enumerate(DATA, 1):
            writer.writerow([idx, title, desc, cat, urg])
            
    print(f"Generated {len(DATA)} records in {target_file}")
    
    # Class distribution summary
    from collections import Counter
    cats = Counter(d[2] for d in DATA)
    print("Class distribution:")
    for cat, count in sorted(cats.items()):
        print(f"  {cat}: {count}")

if __name__ == "__main__":
    main()
